def transform(grid):
 h=len(grid); w=len(grid[0]); seen=set(); objs=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c]==0 or (r,c) in seen: continue
   color=grid[r][c]; stack=[(r,c)]; seen.add((r,c)); cells=[]
   while stack:
    a,b=stack.pop(); cells.append((a,b))
    for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
     if 0<=x<h and 0<=y<w and (x,y) not in seen and grid[x][y]==color:
      seen.add((x,y)); stack.append((x,y))
   objs.append(cells)
 if not objs: return grid
 cells=max(objs,key=lambda s:max(r for r,c in s))
 top=min(r for r,c in cells); bottom=max(r for r,c in cells); left=min(c for r,c in cells); right=max(c for r,c in cells)
 return [row[left:right+1] for row in grid[top:bottom+1]]

